CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE project_status AS ENUM ('draft','verification_pending','verified','seed_live','seed_closed','bonding_live','raise_closed','graduating','graduated','failed','refundable','cancelled');
CREATE TABLE users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),auth_subject TEXT NOT NULL UNIQUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE investor_identities(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL UNIQUE REFERENCES users(id),provider_reference TEXT,eligibility_status TEXT NOT NULL DEFAULT 'unknown',jurisdiction TEXT,expires_at TIMESTAMPTZ,version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE wallets(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id),address TEXT NOT NULL UNIQUE,verified_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE founder_entities(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),entity_type TEXT NOT NULL,display_name TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE founder_memberships(entity_id UUID NOT NULL REFERENCES founder_entities(id),user_id UUID NOT NULL REFERENCES users(id),role TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(entity_id,user_id));
CREATE TABLE projects(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),entity_id UUID NOT NULL REFERENCES founder_entities(id),name TEXT NOT NULL,description TEXT,status project_status NOT NULL DEFAULT 'draft',chain_address TEXT UNIQUE,version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE verifications(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),subject_type TEXT NOT NULL,subject_id UUID NOT NULL,stage TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',provider_reference TEXT,reviewer_id UUID REFERENCES users(id),reviewed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(subject_type,subject_id,stage));
CREATE TABLE listings(project_id UUID PRIMARY KEY REFERENCES projects(id),status TEXT NOT NULL DEFAULT 'draft',submitted_at TIMESTAMPTZ,reviewer_id UUID REFERENCES users(id),reviewed_at TIMESTAMPTZ,review_reason TEXT);
CREATE TABLE offerings(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),project_id UUID NOT NULL REFERENCES projects(id),status TEXT NOT NULL DEFAULT 'draft',allocation_bps JSONB NOT NULL,configuration JSONB NOT NULL DEFAULT '{}',chain_address TEXT UNIQUE,version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE investments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),offering_id UUID NOT NULL REFERENCES offerings(id),identity_id UUID NOT NULL REFERENCES investor_identities(id),wallet_id UUID REFERENCES wallets(id),amount_minor BIGINT NOT NULL CHECK(amount_minor>0),currency CHAR(3) NOT NULL,status TEXT NOT NULL,idempotency_key TEXT NOT NULL UNIQUE,chain_signature TEXT UNIQUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE positions(project_id UUID NOT NULL REFERENCES projects(id),identity_id UUID NOT NULL REFERENCES investor_identities(id),amount NUMERIC(39,0) NOT NULL DEFAULT 0,source TEXT NOT NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(project_id,identity_id));
CREATE TABLE vesting_streams(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),project_id UUID NOT NULL REFERENCES projects(id),identity_id UUID REFERENCES investor_identities(id),provider TEXT NOT NULL,external_stream_id TEXT,start_at TIMESTAMPTZ,end_at TIMESTAMPTZ,claimable NUMERIC(39,0) NOT NULL DEFAULT 0,claimed NUMERIC(39,0) NOT NULL DEFAULT 0,status TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE milestones(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),project_id UUID NOT NULL REFERENCES projects(id),ordinal SMALLINT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',requirements JSONB NOT NULL DEFAULT '{}',UNIQUE(project_id,ordinal));
CREATE TABLE capital_claims(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),milestone_id UUID NOT NULL REFERENCES milestones(id),amount NUMERIC(39,0) NOT NULL,status TEXT NOT NULL DEFAULT 'pending',chain_signature TEXT UNIQUE);
CREATE TABLE escrow_accounts(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),offering_id UUID NOT NULL REFERENCES offerings(id),chain_address TEXT UNIQUE,asset_mint TEXT,observed_balance NUMERIC(39,0));
CREATE TABLE refunds(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),investment_id UUID NOT NULL UNIQUE REFERENCES investments(id),amount NUMERIC(39,0) NOT NULL,status TEXT NOT NULL DEFAULT 'pending',idempotency_key TEXT NOT NULL UNIQUE,chain_signature TEXT UNIQUE);
CREATE TABLE payments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id),provider TEXT NOT NULL,provider_reference TEXT,idempotency_key TEXT NOT NULL UNIQUE,amount_minor BIGINT NOT NULL,currency CHAR(3) NOT NULL,status TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE balance_projections(user_id UUID NOT NULL REFERENCES users(id),asset TEXT NOT NULL,amount NUMERIC(39,0) NOT NULL,as_of_slot BIGINT,updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(user_id,asset));
CREATE TABLE blockchain_transactions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),idempotency_key TEXT NOT NULL UNIQUE,signature TEXT UNIQUE,status TEXT NOT NULL DEFAULT 'created',payload_hash TEXT NOT NULL,last_error TEXT,submitted_at TIMESTAMPTZ,confirmed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE blockchain_events(signature TEXT NOT NULL,event_index INT NOT NULL,slot BIGINT NOT NULL,program_id TEXT NOT NULL,event_type TEXT NOT NULL,payload JSONB NOT NULL,indexed_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(signature,event_index));
CREATE TABLE outbox_events(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),aggregate_type TEXT NOT NULL,aggregate_id TEXT NOT NULL,event_type TEXT NOT NULL,payload JSONB NOT NULL,attempts INT NOT NULL DEFAULT 0,available_at TIMESTAMPTZ NOT NULL DEFAULT now(),processed_at TIMESTAMPTZ);
CREATE TABLE project_updates(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),project_id UUID NOT NULL REFERENCES projects(id),author_id UUID NOT NULL REFERENCES users(id),kind TEXT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,published_at TIMESTAMPTZ);
CREATE TABLE creator_fee_claims(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),project_id UUID NOT NULL REFERENCES projects(id),amount NUMERIC(39,0) NOT NULL,status TEXT NOT NULL DEFAULT 'pending',chain_signature TEXT UNIQUE);
CREATE TABLE audit_logs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),actor_id UUID REFERENCES users(id),action TEXT NOT NULL,target_type TEXT NOT NULL,target_id TEXT,request_id TEXT NOT NULL,reason TEXT,before_state JSONB,after_state JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX project_status_idx ON projects(status);
CREATE INDEX investment_identity_time_idx ON investments(identity_id,created_at DESC);
CREATE INDEX chain_event_slot_idx ON blockchain_events(slot);
CREATE INDEX outbox_available_idx ON outbox_events(available_at) WHERE processed_at IS NULL;
